const update = $input.first().json;
const m = update.message ?? {};
const f = m.from ?? {};
const c = m.chat ?? {};
const d = m.document ?? null;
const cfg = $('Bot Config').first().json;
const filename = d?.file_name ?? '';
const ext = filename.includes('.') ? filename.split('.').pop().toLowerCase() : '';
const text = String(m.text ?? m.caption ?? '');
return [{ json: {
  telegram_update_id: Number(update.telegram_update_id ?? update.update_id ?? 0),
  next_offset: Number(update.next_offset ?? 0),
  sender_id: String(f.id ?? ''), chat_id: String(c.id ?? ''), username: String(f.username ?? ''),
  name: [f.first_name, f.last_name].filter(Boolean).join(' '), text,
  document_file_id: String(d?.file_id ?? ''), document_filename: filename, document_extension: ext,
  reply_to_message_id: m.reply_to_message?.message_id ?? null,
  is_start: /^\/start(?:@\w+)?(?:\s|$)/i.test(text),
  has_document: Boolean(d?.file_id),
  is_supported_document: Boolean(d?.file_id && ['epub','pdf','docx','txt'].includes(ext)),
  received_at: new Date().toISOString(),
  admin_user_id: String(cfg.admin_user_id), admin_chat_id: String(cfg.admin_chat_id),
  is_admin: String(f.id ?? '') === String(cfg.admin_user_id)
} }];

const s = $input.first().json;
const candidates = new Set();
while (candidates.size < 32) candidates.add(Math.floor(100000 + Math.random() * 900000));
return [...candidates].map(task_no => ({ json: { ...s, task_no } }));

const free = $input.all().map(i => i.json).filter(i => Number.isInteger(i.task_no));
if (!free.length) throw new Error('Could not allocate a free six-digit task number. Run the task again.');
return [{ json: free[0] }];

const s = $input.first().json;
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const client = s.username
  ? '@' + escapeHtml(s.username)
  : escapeHtml(s.name || 'без username');
const filename = escapeHtml(s.document_filename);
const nextRetryAt = new Date(Date.now() + 5 * 60 * 1000).toISOString();

return [{ json: {
  ...s,
  next_retry_at: nextRetryAt,
  admin_task_text: `📚 Новая задача #${s.task_no}

Клиент: ${client}
User ID: ${s.sender_id}
Файл: ${filename}
Статус: NEW

Когда перевод будет готов, ответьте на это сообщение готовым файлом.`,
  source_caption: `Задача #${s.task_no} — исходный файл`,
  customer_confirmation_text: `Задача #${s.task_no} принята.

Ориентировочная скорость перевода — до 15 минут на каждые 10 000 знаков.
Фактическое время зависит от объёма и формата книги. Готовый перевод придёт в этот чат.`
} }];

const input = $input.first().json;
if (input.task_no) return [{ json: input }];
const task = $('Insert Task').first().json;
return [{ json: { ...task } }];

const input = $input.first().json;
if (input.task_no) return [{ json: input }];
const task = $('Save Result Pending').first().json;
return [{ json: { ...task } }];

const MAX_RECOVERY_ATTEMPTS = 8;
const MAX_RECOVERIES_PER_RUN = 20;
const BACKOFF_MINUTES = [5, 15, 30, 60, 180, 360, 720, 1440];
const now = Date.now();

return $input.all()
  .map(item => item.json)
  .filter(task => Number(task.retry_count ?? 0) < MAX_RECOVERY_ATTEMPTS)
  .filter(task => {
    if (!task.next_retry_at) return true;
    const retryAt = new Date(task.next_retry_at).getTime();
    return Number.isNaN(retryAt) || retryAt <= now;
  })
  .sort((a, b) => {
    const aTime = new Date(a.updatedAt ?? a.created_at ?? 0).getTime() || 0;
    const bTime = new Date(b.updatedAt ?? b.created_at ?? 0).getTime() || 0;
    return aTime - bTime;
  })
  .slice(0, MAX_RECOVERIES_PER_RUN)
  .map(task => {
    const retryCount = Number(task.retry_count ?? 0) + 1;
    const delayMinutes = BACKOFF_MINUTES[Math.min(retryCount - 1, BACKOFF_MINUTES.length - 1)];
    return {
      json: {
        ...task,
        retry_count: retryCount,
        next_retry_at: new Date(now + delayMinutes * 60 * 1000).toISOString()
      }
    };
  });

const TELEGRAM_BOT_TOKEN = 'PASTE_TELEGRAM_BOT_TOKEN_HERE';
const ADMIN_USER_ID = '0';
let ADMIN_CHAT_ID = '0';

const isUnset = (value) => !value || String(value).trim() === '0';
if (!TELEGRAM_BOT_TOKEN || TELEGRAM_BOT_TOKEN === 'PASTE_TELEGRAM_BOT_TOKEN_HERE') {
  throw new Error('Setup required: open Bot Config and paste the Telegram bot token.');
}
if (isUnset(ADMIN_USER_ID)) throw new Error('Setup required: open Bot Config and set ADMIN_USER_ID.');
if (isUnset(ADMIN_CHAT_ID)) ADMIN_CHAT_ID = ADMIN_USER_ID;
return [{ json: { bot_token: TELEGRAM_BOT_TOKEN, admin_user_id: String(ADMIN_USER_ID), admin_chat_id: String(ADMIN_CHAT_ID) } }];

const row = $input.first().json;
if (row.value === undefined || row.value === null || row.value === '') {
  throw new Error('Polling state could not be initialized. Check bt_bot_state schema.');
}
const raw = String(row.value);
let state;
try {
  state = JSON.parse(raw);
} catch {
  const legacyOffset = Number(raw);
  state = { offset: Number.isFinite(legacyOffset) ? legacyOffset : 0, lockToken: '', lockUntil: 0 };
}
const offset = Math.max(0, Number(state.offset) || 0);
const lockToken = String(state.lockToken || '');
const lockUntil = Number(state.lockUntil) || 0;
const can_poll = !(lockToken && lockUntil > Date.now());
return [{ json: { ...$('Bot Config').first().json, state_raw: raw, offset, lockToken, lockUntil, can_poll } }];

const response = $input.first().json;
const status = Number(response.statusCode ?? 200);
const body = response.body ?? response;
const errorCode = Number(body?.error_code ?? status);
if (status === 409 || errorCode === 409) return [{ json: { action: 'webhook_conflict' } }];
if (status < 200 || status >= 300 || body?.ok !== true) {
  throw new Error('Telegram getUpdates failed: ' + JSON.stringify({ status, body }));
}
const update = Array.isArray(body.result) ? body.result[0] : null;
if (!update) return [{ json: { action: 'idle' } }];
const updateId = Number(update.update_id);
if (!Number.isFinite(updateId)) throw new Error('Telegram update has no valid update_id.');
return [{ json: { action: 'update', ...update, telegram_update_id: updateId, next_offset: updateId + 1, has_message: Boolean(update.message) } }];

const response = $input.first().json;
const status = Number(response.statusCode ?? 200);
const body = response.body ?? response;
if (status < 200 || status >= 300 || body?.ok !== true) {
  throw new Error('Telegram deleteWebhook failed: ' + JSON.stringify({ status, body }));
}
return [];

const update = $input.first().json;
const prepared = $('Prepare Poll Request').first().json;
const expected_state_raw = String(prepared.state_raw);
let state;
try { state = JSON.parse(expected_state_raw); } catch { state = { offset: Number(prepared.offset) || 0 }; }
const lockToken = Date.now() + '-' + Math.random().toString(36).slice(2, 12);
const lockUntil = Date.now() + 120000;
const locked_state_raw = JSON.stringify({ offset: Math.max(0, Number(state.offset) || 0), lockToken, lockUntil });
return [{ json: { ...update, expected_state_raw, locked_state_raw, lockToken, lockUntil } }];

const normalized = $('Normalize + Config').first().json;
const row = $input.first().json ?? {};
const found = row.user_id !== undefined && row.user_id !== null && String(row.user_id) !== '';
const status = found ? String(row.status ?? '').trim().toUpperCase() : 'MISSING';
return [{ json: {
  ...normalized,
  user_found: found,
  user_status: status || 'UNKNOWN',
  request_notified_at: row.request_notified_at ?? null
} }];

const s = $('Normalize + Config').first().json;
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const username = s.username ? '@' + escapeHtml(s.username) : '—';
const name = s.name ? escapeHtml(s.name) : '—';

return [{ json: {
  ...s,
  admin_access_request_text: `👤 Новая заявка на доступ

Имя: ${name}
Username: ${username}
User ID: ${s.sender_id}
Статус: PENDING

Чтобы разрешить доступ, измените status этого пользователя в bt_bot_users на ACTIVE.`,
  customer_access_request_text: 'Заявка на доступ отправлена администратору. После одобрения отправьте /start ещё раз.'
} }];
